import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1203, own='cte_126.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

H("873.d.1.A",3,"A service writer greets a customer, listens to the description of a rattling noise and repeats it back before writing the ticket. She is demonstrating:","effective oral communication with customers and coworkers",["avoiding the customer","interrupting the customer","using only slang"],"Listen, confirm, record.")
H("873.d.1.A",4,"When explaining a repair to a customer with no mechanical background, a technician should:","use plain language and avoid unexplained jargon",["use only technical terms","speak quickly","avoid eye contact"],"Match the explanation to the listener.")
H("873.d.1.B",3,"A technician writes on a repair order exactly what she found, what she replaced and the test results. This shows effective:","written communication with others in the shop",["avoiding documentation","vague notes","guessing"],"Clear repair notes help everyone.")
H("873.d.1.B",4,"A well-written repair note for a coolant leak should include:","the location of the leak, the part replaced and the pressure test result",["only the word 'fixed'","a joke","the customer's favorite color"],"Specific, complete notes.")
H("873.d.1.C",3,"A technician adds the cost of a $42.50 sensor, $18.75 in fluids and $60 in labor to prepare an estimate. She is demonstrating:","mathematical skills in addition for a repair estimate",["avoiding math","guessing","ignoring costs"],"42.50 + 18.75 + 60 = 121.25.")
H("873.d.1.C",4,"A shop charges $85 per hour and a job takes 2.5 hours. The labor cost is:","$212.50",["$187.50","$170.00","$235.00"],"85 × 2.5 = 212.50.")
H("873.d.2.A",3,"A technician looks up a wiring diagram and the manufacturer's recommended service interval in the service manual before repairing a lighting circuit. She is:","locating, reading and interpreting transportation repair and service information",["guessing","skipping the manual","using only memory"],"Use service information.")
H("873.d.2.A",4,"If a technician's memory conflicts with the printed torque value in the service manual, she should:","follow the manufacturer's published specification",["use the larger number","ignore the manual","guess an average"],"Specs come from the manual.")
H("873.d.2.B",3,"A student learns about hybrid drive systems, driver-assist sensors and electric vehicle charging in a transportation class. She is describing:","basic and emerging transportation technologies",["ancient tools only","unrelated hobbies","only paper maps"],"Emerging tech is part of the field.")
H("873.d.2.B",4,"Which is an emerging technology that technicians must now understand?","high-voltage battery systems in electric vehicles",["horse carriages","crank-start engines","hand-cranked windows only"],"EV systems are emerging tech.")
H("873.d.3.A",3,"Before using an impact wrench on lug nuts, a technician wears eye protection, selects the right socket and checks the air line. She is demonstrating:","awareness of the proper way to safely use hand and power tools",["unsafe habits","ignoring rules","careless setup"],"Use tools safely.")
H("873.d.3.A",4,"The correct way to store a power drill after use is to:","unplug or disconnect it and put it away in its place",["leave it plugged in on the floor","drop it","hide it under a bench"],"Safe storage prevents accidents.")
H("873.d.3.B",3,"A technician plugs a scan tool into a car's data port and reads trouble codes from the computer. She is identifying:","diagnostic tools and equipment",["only cleaning tools","hand tools only","decorations"],"Scan tools are diagnostic tools.")
H("873.d.3.B",4,"A digital multimeter is used in a shop to:","measure voltage, resistance and current in circuits",["measure tire tread only","weigh parts","tighten bolts"],"Meters test electrical circuits.")
H("873.d.3.C",3,"A technician picks a torque wrench to tighten a wheel's lug nuts to the specified value. She is:","identifying a hand tool and describing its proper use",["guessing the tool","skipping the spec","using a chisel"],"Torque wrenches apply measured force.")
H("873.d.3.C",4,"A flare-nut wrench is best used on a brake line fitting because it:","grips more of the fitting and reduces rounding",["is cheaper","is longer","slides off easily"],"Flare-nut wrenches protect soft fittings.")
H("874.d.1.A",3,"A small-engine technician refuses to sell a customer a used mower with a known cracked deck without disclosing the defect. He is showing:","ethical and legal responsibilities appropriate to the career",["dishonesty","ignoring the law","avoiding disclosure"],"Be honest about defects.")
H("874.d.1.A",4,"Which action best shows legal responsibility when disposing of old engine oil from a customer's mower?","taking it to an approved recycling collection point",["pouring it down a drain","dumping it on the lawn","burning it"],"Follow disposal laws.")
H("874.d.1.B",3,"A new hire at a repair shop greets customers politely, arrives on time and helps clean the bay. He is demonstrating:","proper etiquette and behavior",["rude habits","lateness","carelessness"],"Courtesy and reliability matter.")
H("874.d.1.B",4,"A customer complains angrily about a delay. The technician should respond by:","listening calmly and explaining the next steps",["arguing","ignoring them","walking away"],"Stay professional.")
H("874.d.1.C",3,"A technician tucks in his shirt, ties back his hair and washes his hands before meeting a customer. This shows appropriate:","personal appearance and hygiene",["careless dress","poor hygiene","a messy appearance"],"Professional appearance.")
H("874.d.1.C",4,"In a small-engine shop, loose clothing and hanging jewelry should be avoided because they can:","get caught in moving parts",["improve safety","reduce noise","save time"],"Prevent entanglement.")
H("874.d.1.D",3,"A student writes an email to a parts supplier asking for a price and then listens carefully to a coworker's instructions on a phone call. He is practicing:","written and oral communication and effective listening",["silence","avoidance","confusion"],"Writing and listening skills.")
H("874.d.1.D",4,"Which habit shows effective listening when a supervisor explains a repair schedule?","taking notes and asking clarifying questions",["texting","interrupting","looking away"],"Active listening.")
H("874.d.1.E",3,"A student reads the engine manual and writes a clear step-by-step procedure for changing spark plugs, including torque values and warnings. He is employing:","technical writing and preparation skills",["jokes","guesses","random notes"],"Technical writing is precise.")
H("874.d.1.E",4,"A good technical procedure includes steps that are:","numbered, specific and in the right order",["vague","unordered","hidden"],"Order and clarity matter.")
H("874.d.1.F",3,"A student explains the four strokes of an engine to the class using a diagram, speaking clearly without notes. He is demonstrating:","effective speaking skills through prepared and extemporaneous presentations",["silence","mumbling","reading silently"],"Speak clearly and confidently.")
H("874.d.1.F",4,"An extemporaneous speech is one that is:","delivered with little advance preparation or script",["read word for word","memorized exactly","silent"],"Extemporaneous means impromptu.")
H("874.d.2.A",3,"A shop begins servicing battery-powered string trimmers and robotic mowers alongside gasoline equipment. This shows how:","emerging technologies affect the small engine technology industry",["technology has no effect","only old tools matter","shops never change"],"New tech changes the trade.")
H("874.d.2.A",4,"Which emerging technology is changing outdoor power equipment?","lithium-ion battery power and electronic controls",["steam engines","hand cranks","sail power"],"Battery tools are growing.")
H("874.d.2.B",3,"A business owner worries about a shortage of trained technicians and rising parts costs. These are:","issues affecting the small engine technology industry",["unrelated topics","weather only","decorations"],"Labor and cost issues.")
H("874.d.2.B",4,"A growing environmental concern for small engines is:","exhaust emissions from older two-stroke engines",["silent operation","lack of fuel","too many batteries"],"Emissions rules affect small engines.")
H("874.d.2.C",3,"A shop learns that EPA rules limit emissions from small off-road engines and updates its repair procedures. This is:","discussing regulations and laws and their impact on the industry",["ignoring laws","breaking rules","avoiding updates"],"Comply with emission laws.")
H("874.d.2.C",4,"A technician who removes an emissions control component from a mower engine may be:","violating federal law and causing fines",["following the law","improving legality","saving money legally"],"Tampering is illegal.")
H("874.d.2.D",3,"A technician subscribes to an outdoor power equipment magazine and reads about a new carburetor recall. He is:","reading written material to stay abreast of current industry issues",["avoiding news","ignoring trends","skipping reading"],"Read to stay current.")
H("874.d.2.D",4,"Reading manufacturer service bulletins regularly helps a technician to:","learn about known problems and updated repair procedures",["avoid training","skip inspections","ignore customers"],"Bulletins carry updates.")
H("874.d.3.A",3,"A student joins a career and technical student organization and helps plan a leadership workshop and a skills contest. She is participating in:","the planning and development of leadership and skill development activities",["avoiding teamwork","skipping meetings","ignoring opportunities"],"CTSOs build leadership.")
H("874.d.3.A",4,"A skills contest in a small-engine class helps a student to:","practice technical skills under timed conditions and receive feedback",["avoid learning","skip safety","reduce teamwork"],"Contests build skills.")
H("874.d.3.B",3,"A student uses the career and technical student organization's scholarship list, mentor network and competitive events to plan her future. She is:","using resources available through a student organization",["ignoring help","avoiding support","wasting resources"],"Use organization resources.")
H("874.d.3.B",4,"Which resource from a career and technical student organization could help a student find industry contacts?","its networking events and mentor program",["a vending machine","a parking pass","a lunch menu"],"Networking events connect students.")
H("874.d.4.A",3,"A shop posts a monthly checklist for inspecting the lifts, cleaning the parts washer and checking fire extinguishers. This is a:","preventative maintenance schedule plan for the facility",["random chore list","vacation plan","sales plan"],"Schedule routine facility checks.")
H("874.d.4.A",4,"A preventative maintenance schedule differs from a repair-only approach because it:","performs service before problems occur",["waits for breakdowns","skips inspection","ignores the schedule"],"PM is proactive.")
H("874.d.4.B",3,"A technician follows the shop's schedule to sharpen mower blades, calibrate the torque wrench and oil the bench grinder. He is using:","the preventative maintenance schedule for tools and equipment",["no schedule","guesswork","random work"],"Maintain tools on schedule.")
H("874.d.4.B",4,"A torque wrench that is not recalibrated on schedule may give:","inaccurate readings and cause over- or under-tightened bolts",["perfect results","faster repairs","shorter wait times"],"Calibration keeps accuracy.")
H("874.d.4.C",3,"After servicing a chainsaw, a technician completes the repair order with the customer's name, the work performed and the parts used. He is completing:","repair orders and paperwork related to small engine work",["avoiding paperwork","hiding steps","losing data"],"Document every repair.")
H("874.d.4.C",4,"The repair order is important for a shop because it:","documents the work done and supports billing and warranty claims",["avoids records","hides costs","slows work"],"Orders support billing and warranty.")
H("874.d.4.D",3,"A technician totals the price of a new carburetor kit, a fuel filter and 1.5 hours of labor to give a customer a quote. He is:","estimating parts and labor costs on a repair order",["guessing","hiding fees","avoiding quotes"],"Estimate parts plus labor.")
H("874.d.4.D",4,"A job needs $24 in parts and 2 hours of labor at $60 per hour. The estimate is:","$144",["$84","$120","$204"],"24 + 120 = 144.")
H("874.d.4.E",3,"A technician looks up the valve clearance specification and the exploded parts diagram in the engine service manual. She is:","locating and interpreting service and repair information",["guessing","skipping the manual","using memory only"],"Use the service manual.")
H("874.d.4.E",4,"A parts breakdown (exploded view) is most useful for:","identifying part names and numbers and seeing how pieces fit together",["choosing paint","setting pay","scheduling shifts"],"Exploded views show assembly.")
H("874.d.5.A",3,"A student writes a proposal to build a small go-kart for the school's engine lab, listing goals, materials and a budget. She is:","developing a project proposal",["avoiding planning","skipping steps","ignoring costs"],"Proposals state goal and budget.")
H("874.d.5.A",4,"A project proposal for a lab build should state:","the purpose, needed parts, cost and a schedule",["only a drawing","only a title","no details"],"Proposals are complete.")
H("874.d.5.B",3,"A student keeps a notebook of each engine rebuild with dates, parts used, measurements and notes. She is:","developing and maintaining records appropriate to small engine technology",["avoiding records","losing data","skipping notes"],"Records document work.")
H("874.d.5.B",4,"Which entry would be most useful when revisiting an engine rebuild a year later?","the measurements taken and the parts replaced with dates",["a doodle","a joke","only 'done'"],"Detailed records help later.")
H("874.d.5.C",3,"A student determines an engine's displacement by multiplying the cylinder's bore area by the stroke and by the number of cylinders. She is describing:","a mathematical formula used for engine calculations",["a random guess","an unrelated task","a paint mix"],"Displacement uses geometry.")
H("874.d.5.C",4,"If a single-cylinder engine's bore area is 5 square inches and its stroke is 2 inches, its displacement is:","10 cubic inches",["7 cubic inches","3 cubic inches","25 cubic inches"],"5 × 2 = 10.")
H("874.d.5.D",3,"A student uses the formula Voltage = Current × Resistance to find how much voltage drops across a resistor in an ignition circuit. She is describing:","a mathematical formula used for electrical calculations",["a plumbing formula","a paint formula","a shipping formula"],"Ohm's relationship.")
H("874.d.5.D",4,"A circuit carries 2 amps through a 6 ohm resistor. The voltage across it is:","12 volts",["3 volts","8 volts","0.33 volts"],"2 × 6 = 12.")
H("874.d.5.E",3,"A technician measures 12 volts across a small engine's coil and 4 ohms of resistance with a digital multimeter, then predicts the current. She is applying:","Ohm's law to a small engine electrical circuit",["Boyle's law","Pascal's law","Newton's law"],"I = V ÷ R.")
H("874.d.5.E",4,"Using Ohm's law, the current in a circuit with 12 volts and 4 ohms is:","3 amps",["48 amps","8 amps","0.33 amps"],"12 ÷ 4 = 3.")
H("874.d.6.A",3,"A technician uses email to send a customer a repair estimate and searches the Internet for a discontinued part. She is using:","personal management software such as email and the Internet",["only paper","no software","a hand tool"],"Email and web aid shop work.")
H("874.d.6.A",4,"Which task is best handled with shop management software?","tracking customer repair orders and parts inventory",["tightening a bolt","sharpening a blade","changing spark plugs"],"Software tracks orders.")
H("874.d.6.B",3,"A landscaper's mowers carry a satellite receiver that records where each machine is and how long it ran. This uses:","global positioning systems (GPS)",["a hand crank","a tire gauge","a feeler gauge"],"GPS tracks location.")
H("874.d.6.B",4,"A geographic information system (GIS) is used to:","map and analyze data tied to locations",["measure valve lash","mix fuel","torque bolts"],"GIS maps location data.")
H("874.d.6.C",3,"A shop plugs a laptop into an engine's electronic control unit to read fault codes. This is:","using computer-based equipment to diagnose an engine",["guessing","hand tuning only","skipping diagnosis"],"Scan tools read codes.")
H("874.d.6.C",4,"A computerized diagnostic tool helps a technician most by:","reading sensor data and fault codes quickly",["replacing safety gear","cutting metal","filling oil"],"Diagnostics speed repair.")
H("874.d.7.A",3,"A customer asks what a small engine could power at her farm. The technician lists pumps, generators, tillers and mowers, describing:","uses and applications of small engines and their components",["only cars","only boats","no uses"],"Small engines power many tools.")
H("874.d.7.A",4,"A small engine on a pressure washer drives:","the pump that produces high-pressure water",["the sail","the wheels of a truck","the lights of a stadium"],"The engine powers the pump.")
H("874.d.7.B",3,"A student identifies the battery, ignition coil, spark plug and kill switch on a mower. She is naming:","components of electrical-electronic systems",["fuel parts only","cooling parts","exhaust parts"],"These are electrical parts.")
H("874.d.7.B",4,"The part that turns low battery voltage into the high voltage a spark plug needs is the:","ignition coil",["air filter","muffler","oil dipstick"],"Coil steps up voltage.")
H("874.d.7.C",3,"A technician compares a single-cylinder, vertical-shaft mower engine with a horizontal-shaft tiller engine. He is studying:","engine designs, components and applications",["paint colors","tire sizes","shop layout"],"Designs fit applications.")
H("874.d.7.C",4,"A vertical-shaft engine is commonly used on a:","rotary lawn mower",["generator only","boat motor only","wheel tractor only"],"Mower blades spin horizontally.")
H("874.d.7.D",3,"A student uses a micrometer, a dial bore gauge and a compression tester on an engine. These are:","engine measuring tools and test equipment",["cleaning supplies","safety signs","paint tools"],"They measure and test.")
H("874.d.7.D",4,"A compression tester helps a technician find:","worn rings or leaking valves",["a dirty windshield","a loose belt on a truck","a flat tire"],"Low compression shows wear.")
H("874.d.7.E",3,"A technician selects a torque wrench, a flywheel puller and a spark plug socket for a tune-up. She is choosing:","tools used for operation, maintenance and repair of small engines",["random tools","only hammers","office supplies"],"Pick tools for the job.")
H("874.d.7.E",4,"A flywheel puller is used to:","remove the flywheel without damaging the crankshaft",["fill the oil","clean the carburetor","sharpen blades"],"Pullers avoid damage.")
H("874.d.7.F",3,"A student lists that a two-cycle engine fires every revolution while a four-cycle engine fires every other revolution. She is:","comparing two-cycle and four-cycle engines",["describing a diesel","describing a motor","describing a sail"],"Two-cycle: one power stroke per turn.")
H("874.d.7.F",4,"A key difference is that a four-cycle engine has a separate:","oil sump, so oil is not mixed with the fuel",["spark plug","gas cap","muffler cover"],"Two-cycles mix oil with fuel.")
H("874.d.7.G",3,"A student explains that the piston compresses the mixture, the crankshaft turns piston motion into rotation and the camshaft opens the valves. She is explaining:","the functions of major engine components",["paint choices","filing methods","shop rules"],"Each part has a job.")
H("874.d.7.G",4,"The crankshaft's main job is to:","convert the piston's up-and-down motion into rotary motion",["filter air","store fuel","cool the exhaust"],"Linear to rotary.")
H("874.d.8.A",3,"A mower will not start. The technician checks fuel, spark and compression in order. This is:","troubleshooting and repairing a small engine",["random replacement","giving up","painting the deck"],"Diagnose systematically.")
H("874.d.8.A",4,"An engine cranks, has fuel and compression, but no spark. The technician should check the:","spark plug, ignition coil and kill-switch wiring",["tire pressure","fuel cap color","blade height"],"Trace the ignition circuit.")
H("874.d.8.B",3,"A technician mixes gasoline and oil at a ratio of 50 to 1 for a two-cycle trimmer. She is:","using the correct fuel mixture for efficiency and engine life",["guessing","using only oil","using no oil"],"Ratios protect the engine.")
H("874.d.8.B",4,"Using too little oil in a two-cycle fuel mix can cause:","engine damage from poor lubrication",["better lubrication","cooler running only","longer life"],"Not enough oil scores parts.")
H("874.d.8.C",3,"A student sets valve lash and uses a timing mark to place the camshaft correctly. She is working on:","valve arrangement positions and valve timing",["paint timing","fuel pricing","tire rotation"],"Valve timing matters.")
H("874.d.8.C",4,"If the valves open at the wrong time, the engine will:","run poorly or not at all",["run perfectly","run quieter only","gain power"],"Timing controls breathing.")
H("874.d.8.D",3,"A technician changes the oil, cleans the cooling fins and checks the air filter. He is performing:","preventative maintenance of the lubrication and cooling systems",["a paint job","a sales call","a rebuild"],"Routine care prevents failures.")
H("874.d.8.D",4,"Clogged cooling fins on an air-cooled engine can cause:","overheating and engine damage",["extra cooling","lower oil use","better fuel economy"],"Fins shed heat.")
H("874.d.8.E",3,"A technician installs a new spark plug, sets the gap and adjusts the carburetor idle screw. He is doing:","routine installations, inspections and adjustments",["a full rebuild","a repaint","a sale"],"Routine service tasks.")
H("874.d.8.E",4,"The spark plug gap is set with a:","wire feeler gauge",["tape measure","bathroom scale","caliper only for blades"],"A gauge sets the gap.")
H("874.d.8.F",3,"A student uses a multimeter, a spark tester and a continuity tester on an ignition system. These are:","electrical testing tools for small engines",["cutting tools","paint tools","gardening tools"],"They test circuits.")
H("874.d.8.F",4,"A continuity tester shows whether:","a wire has an unbroken path for current",["a tire holds air","oil is clean","a blade is sharp"],"Continuity means a complete path.")
H("874.d.8.G",3,"A student measures a crankshaft journal with a micrometer and records 1.000 inch. She is using:","a precision instrument to take measurements",["a guess","a ruler on a map","a scale for weight"],"Micrometers measure precisely.")
H("874.d.8.G",4,"Which tool reads to the nearest thousandth of an inch?","an outside micrometer",["a yardstick","a tape measure","a wooden ruler"],"Micrometers give 0.001 in.")
H("874.d.8.H",3,"A technician compares a cylinder's measured bore with the manufacturer's specification to see if it is worn. He is:","inspecting and measuring engine parts for wear tolerances",["painting parts","polishing parts only","ignoring specs"],"Measure against tolerance.")
H("874.d.8.H",4,"If a measured piston clearance is greater than the specified limit, the part is:","worn beyond tolerance and should be replaced or reconditioned",["perfect","better than new","ready for paint"],"Out of spec means service.")
H("874.d.8.I",3,"A student sees that current through a wire creates a magnetic field, and a moving magnet can create current. She is studying:","the relationship between electric current and magnetic fields",["fuel flow","air flow","oil pressure"],"Electromagnetism links them.")
H("874.d.8.I",4,"A small engine's magneto makes spark by:","moving magnets past a coil to induce voltage",["burning oil","pumping air","stirring fuel"],"Induction produces voltage.")
H("874.d.8.J",3,"A technician notes that metal parts expand when hot and shrink when cold, changing clearances in the engine. This describes:","the effects of heating and cooling on small engines",["fuel pricing","paint drying","tire wear"],"Thermal expansion.")
H("874.d.8.J",4,"Why do engine builders leave small clearances between pistons and cylinders?","parts expand when heated and need room",["to look nice","to save paint","to add noise"],"Clearance allows expansion.")

